import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.CyZTVJbV.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"announcements/v1.26/x-thread-ja.md","filePath":"announcements/v1.26/x-thread-ja.md"}'),i={name:"announcements/v1.26/x-thread-ja.md"};function c(s,e,d,n,l,p){return t(),a("div",null,[...e[0]||(e[0]=[r('<p>1/ kiwa v1.26 リリース — Database 深化 milestone。 v1.14 で land した <code>@kiwa-lab/orm</code> v0.8 (Drizzle / Prisma / Kysely × Postgres / MySQL / SQLite の 3 × 3 provider-backend matrix + testcontainers real driver) の上に、 v1.26 は <strong>8 axis advanced production db semantics</strong> (replication / cdc / logical-replication / mvcc / rls / connection-pool / partitioning / vector-store) を land。 <code>@kiwa-lab/orm</code> v0.8.0 → v0.9.0 minor bump。 288 dialect entry + 72 row fidelity grid + 222 semantics test + 3 dogfood app + tutorial 47-49。</p><p>2/ なぜ 8 axis coverage? 2-3 axis pilot には 3 失敗 mode がある — cross-backend semantics drift (Postgres wal2json と MySQL row-based binlog が silent に食い違う)、 terminal state drift (revoked / exhausted / closed-window guard が pilot axis しか test されない)、 provider overlay drift (Prisma / Drizzle / Kysely が同じ neutral event に translate されるのは全 axis で wiring した場合のみ)。 4 rule SSOT (<code>docs/concepts/db-advanced-testing.md</code>) = 1 axis = 1 file / 1 axis = 5 helper / neutral event over dialect / overlay-for-translation-only は package 越し・ milestone 越し・ fork 越しで db suite 比較可能にする最小 set。</p><p>3/ v1.26-1 orm v0.9 8 axis semantics — <code>packages/orm/src/semantics/*</code> に 40 helper (8 axis × 5 helper) を pure state machine で実装、 adapter / network 依存 0。 <code>createReplicationSession</code> + <code>primaryWrite</code> / <code>markReplicaLagged</code> / <code>startFailover</code> / <code>promoteReplica</code> で streaming replication + read replica lag + failover + promoted-replica。 cdc / logical-replication / mvcc / rls / connection-pool / partitioning / vector-store も同 shape。</p><p>4/ 3 provider × 3 backend × 32 neutral event = 288 dialect entry。 <code>collectFidelityCoverage({ providers, backends })</code> で 3 × 3 × 8 = 72 row fidelity grid collect、 release-gate 用 wiring 完了。 222 新 behavior test で <code>semantics/</code> statement 99.54 % / branch 95.61 % / function 100 %。 SQLite は server-only axes で neutral event 名 fallback、 downstream fanout test も SQLite backend で発火継続。</p><p>5/ v1.26-2 dogfood-postgres-cdc-outbox-app — Postgres 16 logical replication + Debezium-style outbox pattern + Redis Streams consumer + at-least-once + idempotent + backpressure。 5-op adapter (mock は orm CDC + logical-replication + replication + connection-pool session が backing、 real は <code>POSTGRES_BOOTSTRAP</code> env-gated)。 28 vitest + 7 軸 release gate PASS。</p><p>6/ v1.26-3 dogfood-mysql-rls-tenant-app — Nuxt 3 + Prisma + MySQL 8 row-level security + tenant_id 自動 injection + cross-tenant refuse + <code>bypass_rls</code> role window + tamper-evident chain-hash audit log (<code>sha256(prev || entryJson)</code> で mid-insertion が全 downstream hash 破壊)。 5-op adapter (mock は orm RLS session backing、 real は <code>MYSQL_KEY</code> env-gated)。 34 vitest + 7 軸 release gate PASS。</p><p>7/ v1.26-4 dogfood-vector-search-app — Postgres 16 pgvector IVFFlat + HNSW index + cosine/L2 distance + hybrid semantic + BM25 keyword search (vectorWeight <code>[0, 1]</code>、 tie-break document id 昇順) + FNV-folded cacheKey embedding cache + on-demand re-index。 5-op adapter (mock は orm vector-store session backing、 real は <code>VECTOR_KEY</code> env-gated)。 41 vitest + 7 軸 release gate PASS。</p><p>8/ v1.26-5 docs — tutorial 47 (Postgres CDC + outbox) + tutorial 48 (MySQL RLS + tenant) + tutorial 49 (pgvector + hybrid search) + concept doc <code>db-advanced-testing.md</code> 8 axis SSOT + migration <code>v1.25 → v1.26</code> (additive-only) + snippet validation <code>docs-tutorial-v1.26.test.ts</code> (32 test) が全 code snippet を実 <code>@kiwa-lab/orm</code> v0.9 API で走査、 drift 構造的遮断。</p><p>9/ v1.26-6 publish — <code>@kiwa-lab/orm</code> v0.8.0 → v0.9.0 minor bump を npm publish。 plugin.json 1.26.0 + 39 db-focused keyword + Roadmap ✅ v1.26 row + announcement 4 file + release-smoke <code>v1-26-publish.test.ts</code> (7 軸 invariant) + docs-e2e <code>V1_26_PAGES</code> (5 page) + release script filter 確認 (orm は v1.14 から build + publish 両 filter 該当済)。 gh-pages publish (<code>/docs-publish-kiwa</code> 経由)。 Roadmap ... <a href="https://github.com/cardene777/kiwa#roadmap" target="_blank" rel="noreferrer">https://github.com/cardene777/kiwa#roadmap</a> — v1.11 → v1.12 → v1.13 → v1.14 → v1.15 → v1.16 → v1.17 → v1.18 → v1.19 → v1.20 → v1.21 → v1.22 → v1.23 → v1.24 → v1.25 → v1.26 の 16 milestone 連続完遂。</p>',9)])])}const g=o(i,[["render",c]]);export{m as __pageData,g as default};
